class Service:
    def __init__(self, repo):
        self.repo = repo

    def add(self, name):
        if name.strip():
            self.repo.add(name.strip().title())


class FakeRepo:
    def __init__(self):
        self.saved = []

    def add(self, item):
        self.saved.append(item)


fake = FakeRepo()
service = Service(fake)
for name in ["анна", "  ", " борис  ", ""]:
